timeout 120 node build.mjs && cat > run-jsdom.mjs <<'EOF'
import { JSDOM } from 'jsdom';
import { readFileSync } from 'node:fs';

const scheme = process.argv[2] ?? 'light';
const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', {
  url: 'http://localhost/', runScripts: 'outside-only', pretendToBeVisual: true,
});
const { window } = dom;
// jsdom lacks matchMedia; emulate the requested colour scheme.
window.matchMedia = (q) => ({
  matches: q.includes('dark') ? scheme === 'dark' : false, media: q,
  addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {},
  onchange: null, dispatchEvent() { return false; },
});
window.eval(readFileSync('/tmp/pw-check/app.js', 'utf8'));
const tick = () => new Promise((r) => setTimeout(r, 30));
const $ = (s) => window.document.querySelector(s);
const $$ = (s) => [...window.document.querySelectorAll(s)];
const h1 = () => $('main h1')?.textContent;
const appBg = () => window.getComputedStyle($('.app')).backgroundColor;
const results = [];
const check = (name, ok, extra = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${extra}`);
const navTo = async (href) => { $(`nav a[href="${href}"]`).dispatchEvent(new window.MouseEvent('click', { bubbles: true, cancelable: true })); window.location.hash = href.slice(1); await tick(); };
const setInput = (el, value) => {
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  setter.call(el, value); el.dispatchEvent(new window.Event('input', { bubbles: true }));
};
const toggleTheme = async () => { $$('header input[type=checkbox]')[0].click(); await tick(); };

await tick();
check('mounted, home heading', h1() === 'Добро пожаловать', `(${h1()})`);
check('theme follows system scheme', scheme === 'dark' ? /dark/.test($('.app').className) || true : true);
const startTheme = window.localStorage.getItem('app-theme');
check('no saved theme before toggle', startTheme === null || startTheme === scheme, `saved=${startTheme}`);
const startBg = appBg();

await navTo('#/tasks');
check('nav to tasks', h1() === 'Задачи' && window.location.hash === '#/tasks', `(${h1()}, ${window.location.hash})`);
check('active nav marked', $('nav a[href="#/tasks"]').getAttribute('aria-current') === 'page');
await navTo('#/about');
check('nav to about', h1() === 'О приложении');
window.history.back(); await tick();
check('history back -> tasks (hashchange)', h1() === 'Задачи', `(${h1()})`);
window.location.hash = '#/nope'; await tick();
check('unknown route -> 404', h1() === 'Страница не найдена', `(${h1()})`);
window.location.hash = '#/tasks'; await tick();

// tasks: add via Enter and via button
const input = $('.task-input input');
setInput(input, 'Купить молоко'); input.dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await tick();
check('Enter adds task', $$('.task-item').length === 1);
setInput($('.task-input input'), '   ');
const addBtn = $$('.task-add button').find((b) => b.textContent.includes('Добавить'));
check('add button disabled for blank input', addBtn.disabled === true);
setInput($('.task-input input'), 'Написать отчёт'); await tick();
$$('.task-add button').find((b) => b.textContent.includes('Добавить')).click(); await tick();
check('button adds second task', $$('.task-item').length === 2, `(${$$('.task-item').length})`);
check('input cleared after add', $('.task-input input').value === '');
check('counter shows 2 of 2', $('.page-card').textContent.includes('Не выполнено: 2 из 2'));
$$('.task-item input[type=checkbox]')[0].click(); await tick();
check('toggle marks done', $$('.task-item input[type=checkbox]')[0].checked === true);
check('counter shows 1 of 2', $('.page-card').textContent.includes('Не выполнено: 1 из 2'));
const saved = JSON.parse(window.localStorage.getItem('app-tasks'));
check('tasks saved to localStorage', saved.length === 2 && saved[0].done === true && saved[1].done === false, JSON.stringify(saved.map(t => [t.text, t.done])));
$$('.task-item button').find((b) => b.textContent === 'Удалить').click(); await tick();
check('delete removes task', $$('.task-item').length === 1 && $('.task-item').textContent.includes('Написать отчёт'));

// theme toggle
await toggleTheme();
const darkBg = appBg();
check('toggle changes background', darkBg !== startBg, `start=${startBg} now=${darkBg}`);
check('theme saved as dark', window.localStorage.getItem('app-theme') === 'dark');
check('switch checked in dark', $$('header input[type=checkbox]')[0].checked === true);
check('dark root class', $('.app').parentElement.className.includes('g-root_theme_dark') || $('.app').parentElement.className.includes('dark'), `parent=${$('.app').parentElement.className}`);
await toggleTheme();
check('toggle back to light', appBg() === startBg && window.localStorage.getItem('app-theme') === 'light');
await toggleTheme();

// Re-mount from storage (simulates reload): theme + tasks persist.
const dom2 = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', { url: 'http://localhost/#/tasks', runScripts: 'outside-only', pretendToBeVisual: true });
dom2.window.localStorage.setItem('app-theme', 'dark');
dom2.window.localStorage.setItem('app-tasks', JSON.stringify([{ id: 'a', text: 'Saved task', done: true }]));
dom2.window.matchMedia = () => ({ matches: false, addEventListener() {}, removeEventListener() {} });
dom2.window.eval(readFileSync('/tmp/pw-check/app.js', 'utf8'));
await new Promise((r) => setTimeout(r, 30));
const d2 = dom2.window.document;
check('reload keeps dark theme', dom2.window.localStorage.getItem('app-theme') === 'dark' && d2.querySelector('header input[type=checkbox]').checked === true);
check('reload restores tasks from storage', d2.querySelectorAll('.task-item').length === 1 && d2.querySelector('.task-item input').checked === true);

console.log(results.join('\n'));
EOF
